def gcd(a, b):
    if a > b:
        a, b = b, a
    if b % a==0:
        return a
    return gcd(b % a, a)

def line(a, b):
    x0, y0 = a
    x1, y1 = b
    if x0==x1:
        return [True, x1, None]
    else:
        slope_num = (y1-y0)
        slope_den = (x1-x0)
        if slope_num==0:
            num = 0
            den = 1
        else:
            g = gcd(abs(slope_num), abs(slope_den))
            num = slope_num//g
            den = slope_den//g
        inter = den*y0-num*x0
        if inter==0:
            den2 = 1
        else:
            den2 = den
        return [False, num, den, inter, den2]

